<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{GuestServiceRequest,HousekeepingTask,LaundryOrder,LostFoundItem,MaintenanceRequest,MinibarConsumption};
class OperationsDashboardController extends Controller{public function __invoke(){ $p=auth()->user()->property_id;return view('operations.dashboard',['hkPending'=>HousekeepingTask::where('property_id',$p)->whereNotIn('status',['inspected','cancelled'])->count(),'maintenanceOpen'=>MaintenanceRequest::where('property_id',$p)->whereNotIn('status',['closed','cancelled'])->count(),'laundryActive'=>LaundryOrder::where('property_id',$p)->whereNotIn('status',['delivered','cancelled'])->count(),'guestRequests'=>GuestServiceRequest::where('property_id',$p)->whereNotIn('status',['completed','cancelled'])->count(),'lostFound'=>LostFoundItem::where('property_id',$p)->where('status','stored')->count(),'minibarToday'=>MinibarConsumption::where('property_id',$p)->whereDate('recorded_at',today())->sum('total')]);}}
